CREATE TABLE IF NOT EXISTS rm_workspace_mfa_events (
  id INTEGER PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES "user"(id),
  event_type TEXT NOT NULL CHECK(event_type = 'mfa_enabled'),
  actor TEXT NOT NULL CHECK(actor = 'system:better-auth'),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS rm_workspace_mfa_events_user_idx
  ON rm_workspace_mfa_events(user_id, id DESC);

CREATE TRIGGER IF NOT EXISTS rm_workspace_mfa_events_no_update
BEFORE UPDATE ON rm_workspace_mfa_events
BEGIN
  SELECT RAISE(ABORT, 'workspace MFA events are append-only');
END;

CREATE TRIGGER IF NOT EXISTS rm_workspace_mfa_events_no_delete
BEFORE DELETE ON rm_workspace_mfa_events
BEGIN
  SELECT RAISE(ABORT, 'workspace MFA events are append-only');
END;

-- Better Auth flips this field only after its own verified TOTP enrollment.
-- The trigger executes in the same SQLite transaction: every pre-enrollment
-- session is deleted before the flag can be observed by Rentemester.
CREATE TRIGGER IF NOT EXISTS rm_better_auth_mfa_enrollment_revoke_sessions
AFTER UPDATE OF twoFactorEnabled ON "user"
WHEN COALESCE(OLD.twoFactorEnabled, 0) = 0 AND NEW.twoFactorEnabled = 1
BEGIN
  INSERT INTO rm_workspace_mfa_events (user_id, event_type, actor)
  VALUES (NEW.id, 'mfa_enabled', 'system:better-auth');
  DELETE FROM "session" WHERE "userId" = NEW.id;
END;

-- On upgrade, existing MFA users have no prior trigger evidence. Record an
-- equivalent append-only boundary before invalidating every legacy session.
INSERT INTO rm_workspace_mfa_events (user_id, event_type, actor)
  SELECT id, 'mfa_enabled', 'system:better-auth'
    FROM "user"
   WHERE COALESCE(twoFactorEnabled, 0) = 1;

-- A migration may be applied after users already enrolled. Invalidating every
-- existing session once is the only fail-closed upgrade boundary; new sessions
-- are created by Better Auth after the reviewed trigger exists.
DELETE FROM "session";
